solution.reference:
package cache

import "sync"

type Cache struct {
	mu    sync.RWMutex
	items map[string]int
	keys  []string
}

// Returns a pointer: returning Cache by value would copy the mutex.
func NewCache() *Cache {
	return &Cache{items: map[string]int{}}
}

// Pointer receiver: mutates the real struct and locks the real mutex.
func (c *Cache) Set(k string, v int) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.items[k] = v
	c.keys = append(c.keys, k)
}

func (c *Cache) Get(k string) (int, bool) {
	c.mu.RLock()
	defer c.mu.RUnlock()
	v, ok := c.items[k]
	return v, ok
}

// Returns a copy, so the caller cannot mutate our slice or race with Set.
func (c *Cache) Keys() []string {
	c.mu.RLock()
	defer c.mu.RUnlock()
	out := make([]string, len(c.keys))
	copy(out, c.keys)
	return out
}

// Why the original was subtly broken rather than obviously broken:
//
// With the value receiver, c.items[k] = v APPEARED to work, because copying a
// struct copies the map header and both headers point at the same hash table.
// But c.keys = append(...) did not, because append reassigns the slice header,
// and that header belonged to the copy. So Set half-worked, which is the worst
// kind of bug.
//
// The mutex was copied on every call, so each invocation locked a fresh
// unlocked mutex and nothing was ever protected. `go vet` catches this as
// "passes lock by value" - worth having in CI.
//
// Keys() returned the internal slice header, so the caller shared our backing
// array: they could write into it, and reading it while another goroutine ran
// Set was a data race.

