package fetch

type result struct {
	body []byte
	err  error
}

func fetchAll(urls []string) ([][]byte, error) {
	results := make(chan result) // unbuffered

	for _, u := range urls {
		go func(u string) {
			body, err := get(u)
			results <- result{body, err} // blocks forever if nobody receives
		}(u)
	}

	var out [][]byte
	for range urls {
		r := <-results
		if r.err != nil {
			// BUG: returns early, so the remaining goroutines block
			// on their send forever and are never collected.
			return nil, r.err
		}
		out = append(out, r.body)
	}
	return out, nil
}

solution.reference:
package fetch

import (
	"context"

	"golang.org/x/sync/errgroup"
)

// Simplest correct fix: buffer the channel so every send completes even if
// nobody is receiving any more. The goroutines finish and are collected.
func fetchAllBuffered(urls []string) ([][]byte, error) {
	type result struct {
		i    int
		body []byte
		err  error
	}
	results := make(chan result, len(urls)) // <- the fix

	for i, u := range urls {
		go func(i int, u string) {
			body, err := get(u)
			results <- result{i, body, err}
		}(i, u)
	}

	out := make([][]byte, len(urls))
	var firstErr error
	for range urls {
		r := <-results
		if r.err != nil {
			if firstErr == nil {
				firstErr = r.err
			}
			continue
		}
		out[r.i] = r.body // indexed, so order matches urls
	}
	if firstErr != nil {
		return nil, firstErr
	}
	return out, nil
}

// Better in a real service: errgroup cancels the in-flight requests instead of
// waiting for them to finish work whose result will be thrown away.
func fetchAll(ctx context.Context, urls []string) ([][]byte, error) {
	g, ctx := errgroup.WithContext(ctx)
	out := make([][]byte, len(urls))

	for i, u := range urls {
		i, u := i, u // unnecessary from Go 1.22, which scopes loop vars per iteration
		g.Go(func() error {
			body, err := getCtx(ctx, u)
			if err != nil {
				return err // cancels ctx for the others
			}
			out[i] = body // distinct index per goroutine, so no lock needed
			return nil
		})
	}
	if err := g.Wait(); err != nil {
		return nil, err
	}
	return out, nil
}

// Why the original leaked: an unbuffered send blocks until a receiver takes the
// value. Once fetchAll returned early, no receiver existed, so every remaining
// goroutine blocked on `results <- ...` forever. A blocked goroutine is never
// collected - it keeps its stack and everything it captured alive - so in a
// server this grows without bound. The runtime does not report it, because
// deadlock detection only fires when ALL goroutines are asleep.

