solution.reference:
package set

// The constraint is `comparable`, not `any`, because the elements are used as
// map keys and Go requires map keys to support == . `any` would not compile
// here. comparable admits numbers, strings, bools, pointers, channels, and
// structs/arrays of comparable types - and correctly excludes slices, maps and
// funcs, which cannot be compared.
type Set[T comparable] struct {
	items map[T]struct{}
}

// T cannot be inferred from the (empty) argument list, so callers write
// NewSet[int](). Declaring the map type directly - Set[int]{} - is an
// alternative that avoids the explicit instantiation.
func NewSet[T comparable]() *Set[T] {
	return &Set[T]{items: map[T]struct{}{}}
}

func (s *Set[T]) Add(v T) { s.items[v] = struct{}{} }

func (s *Set[T]) Has(v T) bool {
	_, ok := s.items[v]
	return ok
}

func (s *Set[T]) Len() int { return len(s.items) }

// Returns []T, so no type assertion is needed and none can panic.
func (s *Set[T]) Items() []T {
	out := make([]T, 0, len(s.items))
	for v := range s.items {
		out = append(out, v)
	}
	return out
}

// What changed for the caller:
//
//   s := NewSet[int]()
//   s.Add(1)
//   s.Add("two")   // compile error, not a runtime panic
//
//   for _, n := range s.Items() { _ = n + 1 }  // n is int, no assertion
//
// This is exactly the case generics are for: the logic is identical for every
// element type and only the type varies. If the behaviour differed per type,
// an interface would be the right tool instead.

